// ── Helper: Load KAT weights into CfCNetwork ─────────────────────────────────
inline void load_kat_weights(CfCNetwork& net) {
    CfCWeights& w = net.weights_mut();
    for (int i = 0; i < 192; i++) w.W_x[i] = CFC_KAT_W_X[i];
    for (int i = 0; i < 1024; i++) w.W_h[i] = CFC_KAT_W_H[i];
    for (int i = 0; i < 32; i++) w.b[i] = CFC_KAT_B[i];
    for (int i = 0; i < 192; i++) w.W_gx[i] = CFC_KAT_W_GX[i];
    for (int i = 0; i < 1024; i++) w.W_gh[i] = CFC_KAT_W_GH[i];
    for (int i = 0; i < 32; i++) w.b_g[i] = CFC_KAT_B_G[i];
    for (int i = 0; i < 6; i++) w.W_tau[i] = CFC_KAT_W_TAU[i];
    w.b_tau = CFC_KAT_B_TAU;
    for (int i = 0; i < 32; i++) w.W_out[i] = CFC_KAT_W_OUT[i];
    w.b_out = CFC_KAT_B_OUT;
    // Build transposed views
    for (uint32_t d = 0; d < CfCConfig::D_INPUT; d++)
        for (uint32_t h = 0; h < CfCConfig::N_HIDDEN; h++)
            w.W_x_T[d * CfCConfig::N_HIDDEN + h] = w.W_x[h * CfCConfig::D_INPUT + d];
    for (uint32_t d = 0; d < CfCConfig::N_HIDDEN; d++)
        for (uint32_t h = 0; h < CfCConfig::N_HIDDEN; h++)
            w.W_h_T[d * CfCConfig::N_HIDDEN + h] = w.W_h[h * CfCConfig::N_HIDDEN + d];
    for (uint32_t d = 0; d < CfCConfig::D_INPUT; d++)
        for (uint32_t h = 0; h < CfCConfig::N_HIDDEN; h++)
            w.W_gx_T[d * CfCConfig::N_HIDDEN + h] = w.W_gx[h * CfCConfig::D_INPUT + d];
    for (uint32_t d = 0; d < CfCConfig::N_HIDDEN; d++)
        for (uint32_t h = 0; h < CfCConfig::N_HIDDEN; h++)
            w.W_gh_T[d * CfCConfig::N_HIDDEN + h] = w.W_gh[h * CfCConfig::N_HIDDEN + d];
    std::strncpy(w.sha256, CFC_KAT_SHA256, 64);
    w.sha256[64] = 0;
}
